UPDATE hydra_uofs_transfer_item
SET status = #{status},
    phase = #{phase},
    message = #{message},
    error_message = #{errorMessage}
WHERE guid = #{guid}

UPDATE hydra_uofs_transfer_item
SET status = 'RUNNING',
    phase = #{phase},
    done_bytes = #{doneBytes},
    message = #{message}
WHERE guid = #{guid}

UPDATE hydra_uofs_transfer_item
SET retry_count = retry_count + 1
WHERE guid = #{guid}
